const fs = require('fs');
const mineflayer = require('mineflayer');
const { Client, GatewayIntentBits, EmbedBuilder, PermissionFlagsBits, ActivityType } = require('discord.js');
const util = require('minecraft-server-util');

const client = new Client({
    intents: [
            GatewayIntentBits.Guilds,
                    GatewayIntentBits.GuildMessages,
                            GatewayIntentBits.MessageContent
                                ]
                                });

                                // ================= CONFIGURATION =================
                                const TOKEN = process.env.DISCORD_TOKEN || "YOUR_BOT_TOKEN_HERE"; 
                                const STATUS_CHANNEL_ID = process.env.STATUS_CHANNEL_ID || "111111111111111111"; // Status/Tier List Channel ID
                                const CHAT_CHANNEL_ID = process.env.CHAT_CHANNEL_ID || "222222222222222222";     // Minecraft Live Chat Channel ID

                                const JAVA_IP = "beast.roviotech.bond";
                                const JAVA_PORT = 19138;
                                const PE_IP = "beast.roviotech.bond";
                                const PE_PORT = 19138;

                                const BOT_USERNAME = "ShineMC_Bot"; // Yeh bot player ban kar server mein join karega
                                const BOT_PASSWORD = "/login YourPassword123"; // Agar server par AuthMe (/login) laga hai

                                const DATA_FILE = './shinemc_data.json';
                                let statusMessage = null;
                                let mcBot = null;

                                // ================= DATA MANAGEMENT =================
                                const defaultData = {
                                    top_kills: { "Friendlyguy00069": 150, "Sarivox": 120, "VoidStark": 95 },
                                        tiers: { "HT1": ["Friendlyguy00069"], "LT1": ["Sarivox"], "HT2": ["VoidStark"], "LT2": [], "HT3": [] }
                                        };

                                        function loadData() {
                                            if (!fs.existsSync(DATA_FILE)) fs.writeFileSync(DATA_FILE, JSON.stringify(defaultData, null, 4));
                                                return JSON.parse(fs.readFileSync(DATA_FILE, 'utf8'));
                                                }

                                                function saveData(data) {
                                                    fs.writeFileSync(DATA_FILE, JSON.stringify(data, null, 4));
                                                    }

                                                    // ================= MINECRAFT CHAT BRIDGE (NINJA MC STYLE) =================
                                                    function startMinecraftBot() {
                                                        mcBot = mineflayer.createBot({
                                                                host: JAVA_IP,
                                                                        port: JAVA_PORT,
                                                                                username: BOT_USERNAME,
                                                                                        version: false // Auto-detect server version
                                                                                            });

                                                                                                mcBot.on('login', () => {
                                                                                                        console.log(`🟢 [MC Bot] Connected to ${JAVA_IP}:${JAVA_PORT} as ${BOT_USERNAME}`);
                                                                                                                const chatChannel = client.channels.cache.get(CHAT_CHANNEL_ID);
                                                                                                                        if (chatChannel) chatChannel.send("✅ **Server connected | ShineMC Chat Bridge Started**");

                                                                                                                                // Agar server par /register ya /login mangta hai:
                                                                                                                                        setTimeout(() => {
                                                                                                                                                    // mcBot.chat(BOT_PASSWORD); // Uncomment karein agar AuthMe plugin laga hai
                                                                                                                                                            }, 3000);
                                                                                                                                                                });

                                                                                                                                                                    // Server ke saare messages (Chat, Join/Leave, Advancements) Discord par bhejna
                                                                                                                                                                        mcBot.on('messagestr', (message) => {
                                                                                                                                                                                const cleanMsg = message.trim();
                                                                                                                                                                                        if (!cleanMsg) return;

                                                                                                                                                                                                // Ignore spam ya khud ke भेजे hue discord messages
                                                                                                                                                                                                        if (cleanMsg.includes(`[Discord]`)) return;

                                                                                                                                                                                                                const chatChannel = client.channels.cache.get(CHAT_CHANNEL_ID);
                                                                                                                                                                                                                        if (!chatChannel) return;

                                                                                                                                                                                                                                // Ninja MC style Advancements Embed
                                                                                                                                                                                                                                        if (cleanMsg.includes("has made the advancement") || cleanMsg.includes("has completed the challenge")) {
                                                                                                                                                                                                                                                    const advEmbed = new EmbedBuilder()
                                                                                                                                                                                                                                                                    .setDescription(`🏆 **${cleanMsg}**`)
                                                                                                                                                                                                                                                                                    .setColor(0xFFA500);
                                                                                                                                                                                                                                                                                                return chatChannel.send({ embeds: [advEmbed] });
                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                // Normal Chat, Join/Leave & Server Logs
                                                                                                                                                                                                                                                                                                                        chatChannel.send(`**${cleanMsg.replace(/@/g, '@\u200b')}**`);
                                                                                                                                                                                                                                                                                                                            });

                                                                                                                                                                                                                                                                                                                                // Agar server restart ho ya bot kick ho jaye toh 10 sec baad auto-reconnect
                                                                                                                                                                                                                                                                                                                                    mcBot.on('end', (reason) => {
                                                                                                                                                                                                                                                                                                                                            console.log(`🔴 [MC Bot] Disconnected (${reason}). Reconnecting in 10s...`);
                                                                                                                                                                                                                                                                                                                                                    const chatChannel = client.channels.cache.get(CHAT_CHANNEL_ID);
                                                                                                                                                                                                                                                                                                                                                            if (chatChannel) chatChannel.send("⚠️ **Proxy/Server disconnected. Reconnecting...**");
                                                                                                                                                                                                                                                                                                                                                                    setTimeout(startMinecraftBot, 10000);
                                                                                                                                                                                                                                                                                                                                                                        });

                                                                                                                                                                                                                                                                                                                                                                            mcBot.on('error', (err) => {
                                                                                                                                                                                                                                                                                                                                                                                    console.log(`[MC Bot Error]: ${err.message}`);
                                                                                                                                                                                                                                                                                                                                                                                        });
                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                        // ================= LIVE STATUS & LEADERBOARD =================
                                                                                                                                                                                                                                                                                                                                                                                        async function getOnlinePlayers() {
                                                                                                                                                                                                                                                                                                                                                                                            try {
                                                                                                                                                                                                                                                                                                                                                                                                    const res = await util.status(JAVA_IP, JAVA_PORT, { timeout: 5000 });
                                                                                                                                                                                                                                                                                                                                                                                                            return `${res.players.online}/${res.players.max}`;
                                                                                                                                                                                                                                                                                                                                                                                                                } catch {
                                                                                                                                                                                                                                                                                                                                                                                                                        try {
                                                                                                                                                                                                                                                                                                                                                                                                                                    const peRes = await util.statusBedrock(PE_IP, PE_PORT, { timeout: 5000 });
                                                                                                                                                                                                                                                                                                                                                                                                                                                return `${peRes.players.online}/${peRes.players.max}`;
                                                                                                                                                                                                                                                                                                                                                                                                                                                        } catch {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return "0 (Offline)";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                async function buildBoardEmbed() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const data = loadData();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const onlinePlayers = await getOnlinePlayers();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const sortedKills = Object.entries(data.top_kills).sort((a, b) => b[1] - a[1]).slice(0, 10);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const killsText = sortedKills.length > 0
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ? sortedKills.map(([name, kills], i) => `\`#${i + 1}\` **${name}** — \`${kills} Kills\``).join('\n')
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                : "No kills recorded yet.";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const tierText = Object.entries(data.tiers)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            .map(([tier, players]) => `🏆 **${tier}:** ${players.length > 0 ? players.join(', ') : 'None'}`)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    .join('\n');

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return new EmbedBuilder()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                .setTitle("⚔️ ShineMC - Official PvP Server")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        .setDescription(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    "**shinemc is best minecraft pvp server**\n" +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                "🟢 **24/7 uptime**\n" +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            "📶 **Ping is so good**\n" +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        "⚡ **Tps is 20**\n\n" +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    `👥 **ONLINE PLAYER :** \`${onlinePlayers}\`\n\n` +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                `💻 **Java IP:** \`${JAVA_IP}:${JAVA_PORT}\`\n` +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            `📱 **PE IP:** \`${PE_IP}\` | **Port:** \`${PE_PORT}\``
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            .addFields(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        { name: "🔥 Top 10 Kills Leaderboard", value: killsText, inline: false },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    { name: "👑 ShineMC PvP Tier List", value: tierText, inline: false }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    .setColor(0x00FF80)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            .setFooter({ text: "ShineMC Bot • Auto-updates every 60 seconds" })
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    .setTimestamp();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    async function updateStatusBoard() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const onlinePlayers = await getOnlinePlayers();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (client.user) client.user.setActivity(`ShineMC | ${onlinePlayers} Players`, { type: ActivityType.Playing });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const channel = client.channels.cache.get(STATUS_CHANNEL_ID);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (!channel) return;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const embed = await buildBoardEmbed();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            try {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (!statusMessage) statusMessage = await channel.send({ embeds: [embed] });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            else await statusMessage.edit({ embeds: [embed] });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                } catch {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        statusMessage = null;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // ================= DISCORD EVENTS & COMMANDS =================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            client.once('ready', () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                console.log(`✅ Discord Bot Logged in as ${client.user.tag}`);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    updateStatusBoard();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        setInterval(updateStatusBoard, 60000);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            startMinecraftBot(); // Start In-Game Bot
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            client.on('messageCreate', async (message) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (message.author.bot) return;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // 1. Discord to Minecraft Chat (Agar message CHAT_CHANNEL_ID mein aaya hai)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (message.channel.id === CHAT_CHANNEL_ID && !message.content.startsWith('!')) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (mcBot && mcBot.entity) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            mcBot.chat(`[Discord] ${message.author.username}: ${message.content}`);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                message.react('❌'); // Bot server mein online nahi hai
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // 2. Commands (!status, !setkills, !settier)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (!message.content.startsWith('!')) return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const args = message.content.slice(1).trim().split(/ +/);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const command = args.shift().toLowerCase();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (command === 'board' || command === 'status') {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const embed = await buildBoardEmbed();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return message.channel.send({ embeds: [embed] });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (!message.member.permissions.has(PermissionFlagsBits.Administrator)) return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const data = loadData();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (command === 'setkills') {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const [player, killsStr] = args;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const kills = parseInt(killsStr);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (!player || isNaN(kills)) return message.reply("⚠️ Usage: `!setkills <PlayerName> <Kills>`");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        data.top_kills[player] = kills;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                saveData(data);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        await updateStatusBoard();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return message.reply(`✅ **${player}** ke kills set ho gaye: \`${kills} Kills\``);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (command === 'removekills') {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const player = args[0];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (!player || !(player in data.top_kills)) return message.reply("❌ Player nahi mila.");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                delete data.top_kills[player];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        saveData(data);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                await updateStatusBoard();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return message.reply(`🗑️ **${player}** ko Top Kills se hata diya.`);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (command === 'settier') {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const tier = args[0]?.toUpperCase();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const player = args[1];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (!tier || !player) return message.reply("⚠️ Usage: `!settier <Tier> <PlayerName>`");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (!data.tiers[tier]) data.tiers[tier] = [];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        for (const t in data.tiers) data.tiers[t] = data.tiers[t].filter(p => p !== player);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                data.tiers[tier].push(player);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        saveData(data);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                await updateStatusBoard();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return message.reply(`👑 **${player}** ko **${tier}** tier mein daal diya!`);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (command === 'removetier') {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const player = args[0];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (!player) return message.reply("⚠️ Usage: `!removetier <PlayerName>`");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        for (const t in data.tiers) data.tiers[t] = data.tiers[t].filter(p => p !== player);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                saveData(data);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        await updateStatusBoard();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return message.reply(`🗑️ **${player}** ko Tier List se hata diya.`);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    client.login(TOKEN);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    